const a=r=>{if(!r)return"Just now";const e=Date.now()-new Date(r).getTime(),t=Math.floor(e/(1e3*60)),n=Math.floor(t/60),o=Math.floor(n/24);return t<1?"Just now":t<60?`${t} min ago`:n<24?`${n} hr ago`:o===1?"Yesterday":o<7?`${o} days ago`:new Date(r).toLocaleDateString("en-US",{year:"numeric",month:"short",day:"numeric"})},s=r=>{const e=new Date(r),t=String(e.getMonth()+1).padStart(2,"0"),n=String(e.getDate()).padStart(2,"0");return`${e.getFullYear()}-${t}-${n}`};export{s as a,a as f};
